    assert float(accumulated.intersection.numpy()) == 3.0
    assert float(accumulated.union.numpy()) == 5.0
    np.testing.assert_allclose(float(accumulated.result().numpy()), 0.6, atol=1e-6)
    accumulated.reset_state()
    assert float(accumulated.intersection.numpy()) == 0.0
    assert float(accumulated.union.numpy()) == 0.0
    assert float(accumulated.result().numpy()) == 0.0
    accumulated.update_state(tf.constant([[[[1.]]]]), tf.constant([[[[0.5]]]]))
    assert float(accumulated.intersection.numpy()) == 0.0
    print('Accumulation/reset/threshold checks: passed')

